  ('Q4051552', 'PAL', 'Q1344080'),
  ('Q4051552', 'NTSC-J', 'Q1344080'),
  ('Q4051248', 'NTSC-U', 'Q3206072'),
  ('Q5162455', 'NTSC-U', 'Q798642'),
  ('Q5162455', 'NTSC-J', 'Q798642'),
  ('Q5165990', 'NTSC-U', 'Q200491'),
  ('Q5165990', 'NTSC-J', 'Q200491'),
  ('Q5182325', 'NTSC-U', 'Q1358743'),
  ('Q5182325', 'NTSC-J', 'Q1358743'),
  ('Q5183051', 'NTSC-J', 'Q507269'),
  ('Q5191424', 'NTSC-U', 'Q1044563'),
  ('Q5191424', 'NTSC-J', 'Q1044563'),
  ('Q5198147', 'NTSC-J', 'Q4346386'),
  ('Q5220859', 'PAL', 'Q1816614'),
  ('Q5220859', 'NTSC-U', 'Q1816614'),
